// Run first: lists the colleagues of $of. The caller can use this on its own.
query colleagues($of: String) {
    match {
        $p: Person { handle: $of }
        $p worksAt $c
        $m worksAt $c
        $m.handle != $of
    }
    return distinct { $m.handle, $m.name }
}
```

```gq
// GQ has no way to call one query from another, so this repeats the colleagues
// pattern inline and adds a second hop. The caller uses the returned names as is.
query colleagues_of_colleagues($of: String) {
    match {
        $p: Person { handle: $of }
        $p worksAt $c
        $m worksAt $c
        $m.handle != $of
        $m worksAt $d
        $f worksAt $d
        $f.handle != $m.handle
    }
    return distinct { $f.name }
}
